from pathlib import Path
import csv, hashlib, json, re
root = Path('E:/OpenMakaiRanch')
source = root / 'eraMakaiRanch-game-eng-translation'
remake_path = root / 'OpenMakaiRanchGame/data/characters.json'
remake_text = remake_path.read_text(encoding='utf-8-sig')
remake = json.loads(remake_text)
rel = lambda p: p.relative_to(root).as_posix()
sha = lambda p: hashlib.sha256(p.read_bytes()).hexdigest()
fields = {'種族':'race','カテゴリ／種族':'race_category','ジョブ':'occupation','所属身分':'affiliation','身長':'height_label','髪色':'hair_color','髪型':'hair_style','髪特徴':'hair_feature','右目の色':'right_eye_color','左目の色':'left_eye_color','目の特徴':'eye_feature','瞳の形':'eye_shape','識別名':'identity_name','出典作品名':'origin_work'}
flag_fields = {'外見年齢':'apparent_age','身長':'height_mm','カラーコード／髪':'hair_color_code','カラーコード／右目':'right_eye_color_code'}
mapping = {0:'anon',1:'slay',3:'kagura',4:'maria',5:'sharon',6:'noir',100:'ayaka',101:'en',102:'yukina'}
rows = []
files = sorted((p for p in source.rglob('*') if p.is_file() and re.fullmatch(r'Chara.*\.csv',p.name,re.I)),key=lambda p:rel(p))
for p in files:
    metadata = {}
    cues = []
    for line,s in enumerate(p.read_text(encoding='utf-8-sig').splitlines(),1):
        if not s.strip() or s.lstrip().startswith(';'): continue
        row = [x.strip() for x in next(csv.reader([s]),[])]
        key = value = None
        if len(row)>=2 and row[0] in {'番号','名前','呼び名'}:
            key={'番号':'source_id','名前':'full_name','呼び名':'display_name'}[row[0]]; value=row[1]
        elif len(row)>=3 and row[0]=='CSTR' and row[1] in fields:
            key=fields[row[1]]; value=row[2]
        elif len(row)>=3 and row[0]=='フラグ' and row[1] in flag_fields:
            key=flag_fields[row[1]]; value=row[2]
        elif len(row)>=2 and row[0]=='素質' and row[1] in {'童顔','ＪＫ'}:
            cues.append({'source_file':rel(p),'line':line,'source_value':row[1], 'meaning':{'童顔':'baby-faced/youthful-face trait','ＪＫ':'schoolgirl/high-school-girl context marker'}[row[1]]})
        if key is not None:
            if key in {'source_id','apparent_age','height_mm'}: value=int(value)
            metadata.setdefault(key,[]).append({'value':value,'source_file':rel(p),'line':line,'source_key':','.join(row[:-1])})
    sid=metadata['source_id'][0]['value']; age=metadata.get('apparent_age',[{'value':None}])[0]['value']
    mm=metadata.get('height_mm',[{'value':None}])[0]['value']
    rid=mapping.get(sid)
    rows.append({'source_id':sid,'source_file':rel(p),'source_sha256':sha(p),'role':'player' if sid==0 else 'template_or_sample' if sid in (2,200) else 'hero','metadata':metadata,'height_cm':mm/10 if mm is not None else None,'height_cm_basis':'source millimeters divided by 10; sample Chara200 line 340 documents millimeters','apparent_age':age,'confirmed_age':None,'confirmed_age_status':'unknown; apparent age is not chronological age','age_context_cues':cues,'visual_review':'not_performed; no images loaded','adult_presentation_status':'blocked_minor_apparent_age' if age is not None and age<18 else 'blocked_pending_age_and_design_review','remake_id':rid,'mapping_confidence':'supported_metadata_correspondence_not_explicit_numeric_foreign_key' if rid else 'no_supported_match','mapping_basis':'Chara1 identity スレイ, blonde short hair, blue eyes, 144cm, foundling correspond to slay; Surei and Slay are retained as distinct source/remake labels' if sid==1 else 'display name and neutral race/height/hair/eye/occupation correspondence' if rid else 'No matching definition in characters.json; do not force template mapping'})
rows.sort(key=lambda x:x['source_id'])
allowed = {'Id','DisplayName','Race','JobClass','Height','HairColor','HairStyle','EyeColor','EyeFeature','Age','ApparentAge','ConfirmedAge'}
remake_rows=[]
for c in remake:
    rid=c['Id']; line=next(i for i,s in enumerate(remake_text.splitlines(),1) if re.search(r'"Id"\s*:\s*"'+re.escape(rid)+r'"',s))
    neutral={}
    for k,v in c.items():
        if k in allowed:
            field_line=next((i for i,s in enumerate(remake_text.splitlines(),1) if i>=line and re.search(r'"'+re.escape(k)+r'"\s*:',s)),None)
            neutral[k]={'value':v,'source_file':rel(remake_path),'line':field_line}
    remake_rows.append({'id':rid,'source_file':rel(remake_path),'id_line':line,'metadata':neutral,'mapped_source_ids':[x['source_id'] for x in rows if x['remake_id']==rid],'age_fields_present':[k for k in c if 'age' in k.lower() and k not in {'BodyImagePath'}], 'confirmed_age':None,'visual_review':'not_performed','adult_presentation_status':'blocked_pending_validation','note':'Remake player-role definition; similar to Chara0/anon but no independently supported source-ID mapping. Not Chara2.' if rid=='rancher' else None})
code_files=['src/Core/Resources/GameDefinitions.cs','src/Core/Models/SaveModels.cs','src/Data/DataRegistry.cs','src/Gameplay/CharacterGenerationPools.cs','src/Gameplay/SaveStateFactory.cs','src/Gameplay/SaveService.cs','src/Gameplay/SaveMigrator.cs','src/App/GameRoot.cs','src/Ui/UiShellController.Screens.cs','src/Gameplay/MatureServices.cs','src/Gameplay/PortraitRenderer.cs']
manifest=[{'file':rel(remake_path),'sha256':sha(remake_path)}]+[{'file':'OpenMakaiRanchGame/'+n,'sha256':sha(root/'OpenMakaiRanchGame'/n)} for n in code_files]
print(json.dumps({'schema_version':1,'scope':'Neutral identity/age/height/race/occupation/hair/eye metadata only. Source read-only. No imagery or sexual dialogue reproduced. Static audit; no runtime safety certification.','source_glob':'eraMakaiRanch-game-eng-translation/**/Chara*.csv (case-insensitive filename comparison)','age_semantics_evidence':{'file':next(x['source_file'] for x in rows if x['source_id']==200),'line':316,'summary':'Comment states this is apparent age; actual age is not implemented because races and elapsed years complicate it.'},'source_characters':rows,'remake_characters':remake_rows,'input_manifest':manifest},ensure_ascii=False))
